// Parsear la respuesta del AI Agent y detectar si es una acción de Odoo
const texto = $json.output || $json.text || $json.response || $json.message || '';

let data;
try {
  const m = texto.match(/```json\s*([\s\S]*?)\s*```/) || texto.match(/{[\s\S]*}/);
  data = m ? JSON.parse(m[1] || m[0]) : JSON.parse(texto);
} catch (e) {
  data = { accion: 'conversar', respuesta_usuario: typeof texto === 'string' ? texto : JSON.stringify(texto) };
}

if (!data || typeof data !== 'object') {
  data = { accion: 'conversar', respuesta_usuario: String(texto) };
}

const accionesOdoo = [
  'crear_contacto', 'actualizar_contacto', 'crear_lead', 'crear_ticket',
  'consultar_producto', 'consultar_stock', 'consultar_cliente', 'consultar_tarea', 'consultar_orden_trabajo'
];
data.es_odoo = accionesOdoo.includes(data.accion);
data.campos = data.campos || {};

console.log('🔎 Acción detectada:', data.accion, '| es_odoo:', data.es_odoo);
return [data];

// Construir el payload JSON-RPC execute_kw según la acción decidida por el AI Agent
const uid = $json.result;
if (!uid) {
  throw new Error('No se pudo autenticar en Odoo (uid vacío). Revisa db/usuario/contraseña.');
}

const a = $('Parsear Acción').first().json;
const c = a.campos || {};

const DB = 'lsanchezgoshawk-bot18-main-34233791';
const PASS = 'admin';

let model, method, valores;

switch (a.accion) {
  // --- CREACIÓN / ACTUALIZACIÓN ---
  case 'crear_contacto':
    model = 'res.partner';
    method = 'create';
    valores = [{ name: c.nombre || c.name, email: c.email, phone: c.telefono || c.phone, mobile: c.movil || c.mobile }];
    break;
  case 'actualizar_contacto':
    model = 'res.partner';
    method = 'write';
    valores = [[parseInt(c.id || c.contact_id, 10)], { name: c.nombre, email: c.email, phone: c.telefono, mobile: c.movil }];
    break;
  case 'crear_lead':
    model = 'crm.lead';
    method = 'create';
    valores = [{ name: c.titulo || c.name, contact_name: c.nombre_contacto, phone: c.telefono, email_from: c.email, description: c.descripcion }];
    break;
  case 'crear_ticket':
    model = 'helpdesk.ticket';
    method = 'create';
    valores = [{ name: c.asunto || c.name, description: c.descripcion, partner_email: c.email, partner_phone: c.telefono }];
    break;
  // --- CONSULTAS (search_read: [ dominio, campos, offset, limite ]) ---
  case 'consultar_producto':
    model = 'product.template';
    method = 'search_read';
    valores = [[['name', 'ilike', c.producto || c.nombre || '']], ['name', 'default_code', 'list_price', 'qty_available'], 0, 10];
    break;
  case 'consultar_stock':
    model = 'product.product';
    method = 'search_read';
    valores = [[['name', 'ilike', c.producto || c.nombre || '']], ['name', 'default_code', 'qty_available', 'virtual_available'], 0, 10];
    break;
  case 'consultar_cliente':
    model = 'res.partner';
    method = 'search_read';
    valores = [[['name', 'ilike', c.nombre || c.cliente || '']], ['name', 'email', 'phone', 'mobile', 'city'], 0, 10];
    break;
  case 'consultar_tarea':
    model = 'project.task';
    method = 'search_read';
    valores = [[['name', 'ilike', c.tarea || c.nombre || '']], ['name', 'stage_id', 'project_id', 'user_ids'], 0, 10];
    break;
  case 'consultar_orden_trabajo':
    model = 'mrp.workorder';
    method = 'search_read';
    valores = [[['name', 'ilike', c.referencia || c.nombre || '']], ['name', 'state', 'product_id', 'duration_expected'], 0, 10];
    break;
  default:
    throw new Error('Acción de Odoo no reconocida: ' + a.accion);
}

// Eliminar campos vacíos/undefined de los diccionarios de valores (solo aplica a create/write)
function limpiar(o) {
  if (Array.isArray(o)) return o.map(limpiar);
  if (o && typeof o === 'object') {
    const r = {};
    for (const k of Object.keys(o)) {
      if (o[k] !== undefined && o[k] !== null && o[k] !== '') r[k] = o[k];
    }
    return r;
  }
  return o;
}

const esConsulta = method === 'search_read';

const payload = {
  jsonrpc: '2.0',
  method: 'call',
  params: {
    service: 'object',
    method: 'execute_kw',
    args: [DB, uid, PASS, model, method, esConsulta ? valores : limpiar(valores)]
  },
  id: Math.floor(Math.random() * 1000000)
};

console.log('📦 Payload Odoo:', JSON.stringify(payload, null, 2));
return [{ payload, accion: a.accion, model, respuesta_usuario: a.respuesta_usuario || '' }];

options.systemMessage:
Eres un agente que recibe mensajes o llamadas provenientes de Spoki y decide qué hacer.

Tienes dos capacidades:

1) ACCIONES SOBRE SPOKI: usa las herramientas del MCP de Spoki directamente cuando la necesidad sea sobre Spoki (contactos de Spoki, listas, plantillas, enviar mensaje, automatizaciones, tickets de Spoki, reportes, etc). Herramientas disponibles: create_custom_field, create_list, create_ticket, delete_list, get_account_report, get_automation, get_automation_steps, get_contact, get_custom_field, get_list, list_accounts, list_automations, list_contact_lists, list_contacts, list_custom_fields, list_lists, list_reports, list_templates, list_tickets, remove_all_contacts_from_list, remove_contacts_from_list, send_message, start_automation, sync_contact, sync_contacts_to_list, update_list.

2) ACCIONES SOBRE ODOO: cuando la necesidad sea registrar o consultar algo en Odoo, NO uses herramientas. En su lugar responde ÚNICAMENTE con un JSON válido (sin texto adicional, sin markdown) con esta forma:
{
  "accion": "<nombre_accion>",
  "campos": { ... },
  "respuesta_usuario": "texto breve confirmando lo que se hará"
}

ACCIONES DE CREACIÓN/ACTUALIZACIÓN:
- crear_contacto (res.partner): { "nombre": "...", "email": "...", "telefono": "...", "movil": "..." }
- actualizar_contacto (res.partner): { "id": <id numérico de odoo>, "nombre": "...", "email": "...", "telefono": "...", "movil": "..." }
- crear_lead (crm.lead): { "titulo": "...", "nombre_contacto": "...", "telefono": "...", "email": "...", "descripcion": "..." }
- crear_ticket (helpdesk.ticket): { "asunto": "...", "descripcion": "...", "email": "...", "telefono": "..." }

ACCIONES DE CONSULTA (solo lectura):
- consultar_producto (product.template): { "producto": "nombre o código a buscar" }
- consultar_stock (product.product): { "producto": "nombre o código a buscar" }
- consultar_cliente (res.partner): { "nombre": "nombre del cliente a buscar" }
- consultar_tarea (project.task): { "tarea": "nombre de la tarea a buscar" }
- consultar_orden_trabajo (mrp.workorder): { "referencia": "referencia o nombre de la orden a buscar" }

Usa SIEMPRE datos reales extraídos del mensaje o llamada, nunca valores inventados. Si un dato no está, deja el campo vacío. Para cualquier cosa que no sea una acción de Odoo ni de Spoki, responde con JSON { "accion": "conversar", "respuesta_usuario": "..." }.

