// DIAGNOSTICO: mensaje en texto plano ASCII, sin emojis ni saltos de linea
const parsed = $('Parsear Acción').first().json || {};
const accion = parsed.accion || 'conversar';
const campos = parsed.campos || {};

const esOdoo = ($json.result !== undefined) || ($json.error !== undefined);

if (!esOdoo) {
  const msg = parsed.respuesta_usuario || 'De acuerdo.';
  return [{ success: true, accion, mensaje: msg, resultado: null }];
}

if ($json.error) {
  const err = $json.error;
  const detalle = typeof err === 'string'
    ? err
    : ((err.data && (err.data.message || err.data.debug)) || err.message || 'Error desconocido en Odoo');
  return [{
    success: false,
    accion,
    mensaje: 'ERROR: no se pudo completar la accion ' + accion + ' en Odoo. ' + String(detalle).replace(/[\r\n]+/g, ' '),
    error: detalle,
    resultado: null
  }];
}

const result = $json.result;
let mensaje = '';

switch (accion) {
  case 'crear_contacto':
    mensaje = 'Contacto creado en Odoo (ID ' + result + ')' + (campos.nombre ? ': ' + campos.nombre : '') + '.';
    break;
  case 'actualizar_contacto':
    mensaje = 'Contacto ' + (campos.id || '') + ' actualizado correctamente en Odoo.';
    break;
  case 'crear_lead':
    mensaje = 'Oportunidad creada en Odoo (ID ' + result + ')' + (campos.titulo ? ': ' + campos.titulo : '') + '.';
    break;
  case 'crear_ticket':
    mensaje = 'Ticket de soporte creado en Odoo (ID ' + result + ')' + (campos.asunto ? ': ' + campos.asunto : '') + '.';
    break;
  case 'consultar_producto':
  case 'consultar_stock':
  case 'consultar_cliente':
  case 'consultar_tarea':
  case 'consultar_orden_trabajo': {
    const filas = Array.isArray(result) ? result : [];
    if (filas.length === 0) {
      mensaje = 'No se encontraron resultados en Odoo para tu consulta.';
    } else {
      const lineas = filas.map(function (r) {
        const nombre = r.name || r.display_name || ('ID ' + r.id);
        const extras = [];
        if (r.default_code) extras.push('ref ' + r.default_code);
        if (r.list_price !== undefined) extras.push('precio ' + r.list_price);
        if (r.qty_available !== undefined) extras.push('stock ' + r.qty_available);
        if (r.virtual_available !== undefined) extras.push('previsto ' + r.virtual_available);
        if (r.email) extras.push(String(r.email));
        if (r.phone) extras.push(String(r.phone));
        if (r.state) extras.push('estado ' + r.state);
        return nombre + (extras.length ? ' (' + extras.join(', ') + ')' : '');
      });
      mensaje = filas.length + ' resultado(s): ' + lineas.join(' | ');
    }
    break;
  }
  default:
    mensaje = 'Accion ' + accion + ' ejecutada. Resultado: ' + JSON.stringify(result);
}

return [{ success: true, accion, mensaje, resultado: result }];

const telefono = $('Webhook').first().json.body.data.from_phone;
